extern "C" unsigned int strlen(const char *);

class stringx
{
  char data[16];
public:
  stringx();
  stringx(const stringx &);
  ~stringx();
  stringx &operator=(const char *);
  void append(const char *, int = -1);
  void append(char c) { append(&c, 1); }
  void to_upper();
};

class FEMenuEntry
{
public:
  int entry_num;
};

class TextString
{
public:
  virtual void changeText(stringx);
};

class HelpbarFE
{
public:
  void Reset();
  void Reformat();
};

struct FEManager
{
  char pad[0x156a4];
  HelpbarFE *helpbar;
};

class SaveLoadFrontEnd
{
  char pad[0x32b4];
public:
  bool in_frontend;
};

class FEGraphicalMenu
{
protected:
  char pad0[0x4c];
  FEMenuEntry *highlighted;
  char pad1[0x74 - 0x50];
public:
  virtual void setHigh(FEMenuEntry *, bool = true);
  virtual void OnActivate();
protected:
  char pad2[0x13c - 0x78];
  FEManager *manager;
};

class FEMultiMenu : public FEGraphicalMenu
{
};

class Career
{
public:
  int GetSurferIdx();
};

struct SurferData
{
  char pad[444];
  char firstname[32];
  char lastname[32];
  char rest[144];
};

extern Career *g_career;
extern SurferData SurferDataArray[];

class KeyboardMenu : public FEMultiMenu
{
  FEMenuEntry *ent[40];
  TextString *filename;
  TextString *enter_text;
  TextString *name_text;
  SaveLoadFrontEnd *sl_parent;
  char pad3[0x3fc - 0x210];
  stringx name;
  bool default_cleared;
public:
  void TurnPQ(bool);
  void KeyOn(int, bool);
  void Switch(FEMenuEntry *, FEMenuEntry *);
  virtual void OnActivate();
};

void KeyboardMenu::OnActivate()
{

	TurnPQ(true);
	FEMultiMenu::OnActivate();
	KeyOn(highlighted->entry_num, true);

	if(sl_parent->in_frontend)
	{
		manager->helpbar->Reset();
		manager->helpbar->Reformat();
	}

	name = "";
	if (strlen(SurferDataArray[g_career->GetSurferIdx()].lastname) > 0)
	{
		name.append(SurferDataArray[g_career->GetSurferIdx()].firstname[0]);
		name.append(' ');
		name.append(SurferDataArray[g_career->GetSurferIdx()].lastname);
		name.to_upper();
	}
	else
	{
		name.append(SurferDataArray[g_career->GetSurferIdx()].firstname);
		name.to_upper();
	}
	filename->changeText(name);
	default_cleared = false;

	Switch(highlighted, ent[38]);
	setHigh(ent[38]);
}
